import type { SpellEntry } from '../types'

// Magias do SRD 5.1 (2º nível), traduzidas para o português do Brasil. Alcances em metros.
export const SPELLS_NIVEL2: SpellEntry[] = [
  { key: "acid_arrow", name: "Flecha Ácida", original: "Acid Arrow", level: 2, school: "evocation", castingTime: "1 ação", range: "27 metros", components: {"v": true, "s": true, "m": "folha de ruibarbo em pó e estômago de uma víbora"}, duration: "Instantânea", classes: ["wizard"], text: ["Uma flecha verde e cintilante atravessa o ar em direção a um alvo ao alcance e explode num jato de ácido. Faça um ataque de magia à distância contra o alvo. Se acertar, o alvo sofre 4d4 de dano de ácido imediatamente e 2d4 de dano de ácido no fim do seu próximo turno. Se errar, a flecha respinga ácido no alvo, causando metade do dano inicial e nenhum dano no fim do seu próximo turno."], higher: "Quando você conjura esta magia usando um espaço de magia de 3º nível ou superior, o dano (inicial e posterior) aumenta em 1d4 para cada nível do espaço acima do 2º." },
  { key: "aid", name: "Auxílio", original: "Aid", level: 2, school: "abjuration", castingTime: "1 ação", range: "9 metros", components: {"v": true, "s": true, "m": "uma pequena tira de pano branco"}, duration: "8 horas", classes: ["cleric", "paladin"], text: ["Sua magia fortalece seus aliados com resistência e determinação. Escolha até três criaturas ao alcance. O máximo de pontos de vida e os pontos de vida atuais de cada alvo aumentam em 5 pela duração."], higher: "Quando você conjura esta magia usando um espaço de magia de 3º nível ou superior, os pontos de vida de um alvo aumentam em 5 adicionais para cada nível do espaço acima do 2º." },
  { key: "alter_self", name: "Alterar-se", original: "Alter Self", level: 2, school: "transmutation", concentration: true, castingTime: "1 ação", range: "Pessoal", components: {"v": true, "s": true}, duration: "Concentração, até 1 hora", classes: ["sorcerer", "wizard"], text: ["Você assume uma forma diferente. Ao conjurar a magia, escolha uma das opções a seguir, cujos efeitos duram pela duração da magia. Enquanto a magia durar, você pode encerrar uma opção com uma ação para receber os benefícios de outra.", "Adaptação Aquática. Você adapta o corpo a um ambiente aquático, brotando guelras e membranas entre os dedos. Você pode respirar debaixo d'água e recebe deslocamento de natação igual ao seu deslocamento de caminhada.", "Mudar Aparência. Você transforma sua aparência. Você decide como é, incluindo altura, peso, traços faciais, som da voz, comprimento do cabelo, coloração e características marcantes, se houver. Você pode se fazer parecer um membro de outra raça, embora nenhuma de suas estatísticas mude. Você também não pode parecer uma criatura de tamanho diferente do seu, e sua forma básica permanece a mesma; se for bípede, por exemplo, não pode usar esta magia para se tornar quadrúpede. A qualquer momento durante a magia, você pode usar sua ação para mudar a aparência desse modo novamente.", "Armas Naturais. Você faz crescer garras, presas, espinhos, chifres ou outra arma natural à sua escolha. Seus golpes desarmados causam 1d6 de dano contundente, perfurante ou cortante, conforme a arma natural escolhida, e você é proficiente com seus golpes desarmados. Por fim, a arma natural é mágica e você tem +1 de bônus nas jogadas de ataque e de dano feitas com ela."] },
  { key: "animal_messenger", name: "Mensageiro Animal", original: "Animal Messenger", level: 2, school: "enchantment", ritual: true, castingTime: "1 ação", range: "9 metros", components: {"v": true, "s": true, "m": "um pedaço de comida"}, duration: "24 horas", classes: ["bard", "druid", "ranger"], text: ["Por meio desta magia, você usa um animal para entregar uma mensagem. Escolha um animal Miúdo que possa ver ao alcance, como um esquilo, um gaio-azul ou um morcego. Você especifica um local, que precisa ter visitado, e um destinatário que corresponda a uma descrição geral, como \"um homem ou mulher vestido com o uniforme da guarda da cidade\" ou \"um anão ruivo usando um chapéu pontudo\". Você também fala uma mensagem de até vinte e cinco palavras. O animal alvo viaja pela duração da magia em direção ao local especificado, percorrendo cerca de 75 km a cada 24 horas se for um mensageiro voador, ou 37,5 km para outros animais.", "Quando o mensageiro chega, ele entrega sua mensagem à criatura que você descreveu, reproduzindo o som da sua voz. O mensageiro só fala com uma criatura que corresponda à descrição dada. Se o mensageiro não chegar ao destino antes de a magia terminar, a mensagem se perde, e o animal volta ao lugar onde você conjurou a magia."], higher: "Se você conjurar esta magia usando um espaço de magia de 3º nível ou superior, a duração da magia aumenta em 48 horas para cada nível do espaço acima do 2º." },
  { key: "arcane_lock", name: "Tranca Arcana", original: "Arcane Lock", level: 2, school: "abjuration", castingTime: "1 ação", range: "Toque", components: {"v": true, "s": true, "m": "pó de ouro no valor de pelo menos 25 po, que a magia consome"}, duration: "Até ser dissipada", classes: ["wizard"], text: ["Você toca uma porta, janela, portão, baú ou outra entrada fechada, e ela fica trancada pela duração. Você e as criaturas que designar ao conjurar a magia podem abrir o objeto normalmente. Você também pode definir uma senha que, quando dita a até 1,5 metro do objeto, suprime esta magia por 1 minuto. Caso contrário, ele é intransponível até ser quebrado ou até a magia ser dissipada ou suprimida. Conjurar arrombar no objeto suprime tranca arcana por 10 minutos.", "Enquanto afetado por esta magia, o objeto é mais difícil de quebrar ou forçar; a CD para quebrá-lo ou abrir quaisquer fechaduras dele aumenta em 10."] },
  { key: "arcanists_magic_aura", name: "Aura Mágica do Arcanista", original: "Arcanist's Magic Aura", level: 2, school: "illusion", castingTime: "1 ação", range: "Toque", components: {"v": true, "s": true, "m": "um pequeno quadrado de seda"}, duration: "24 horas", classes: ["wizard"], text: ["Você coloca uma ilusão numa criatura ou objeto que tocar, de modo que magias de adivinhação revelem informações falsas sobre ele. O alvo pode ser uma criatura voluntária ou um objeto que não esteja sendo carregado ou vestido por outra criatura.", "Ao conjurar a magia, escolha um ou ambos os efeitos a seguir. O efeito dura pela duração. Se você conjurar esta magia na mesma criatura ou objeto todos os dias por 30 dias, aplicando o mesmo efeito a cada vez, a ilusão dura até ser dissipada.", "Aura Falsa. Você muda a forma como o alvo aparece para magias e efeitos mágicos, como detectar magia, que detectam auras mágicas. Você pode fazer um objeto não mágico parecer mágico, um objeto mágico parecer não mágico ou mudar a aura mágica do objeto para que pareça pertencer a uma escola de magia específica à sua escolha. Ao usar este efeito num objeto, você pode tornar a falsa magia aparente para qualquer criatura que manuseie o item.", "Máscara. Você muda a forma como o alvo aparece para magias e efeitos mágicos que detectam tipos de criatura, como o Sentido Divino de um paladino ou o gatilho da magia símbolo. Você escolhe um tipo de criatura, e outras magias e efeitos mágicos tratam o alvo como se fosse uma criatura desse tipo ou desse alinhamento."] },
  { key: "augury", name: "Augúrio", original: "Augury", level: 2, school: "divination", ritual: true, castingTime: "1 minuto", range: "Pessoal", components: {"v": true, "s": true, "m": "varetas, ossos ou fichas semelhantes marcados de forma especial, no valor de pelo menos 25 po"}, duration: "Instantânea", classes: ["cleric"], text: ["Lançando varetas incrustadas de gemas, rolando ossos de dragão, dispondo cartas ornamentadas ou empregando outro instrumento de adivinhação, você recebe um presságio de uma entidade de outro mundo sobre os resultados de uma ação específica que planeja realizar nos próximos 30 minutos. O Mestre escolhe entre os seguintes presságios possíveis:", "• Bem, para bons resultados", "• Mal, para maus resultados", "• Bem e mal, para resultados bons e maus", "• Nada, para resultados que não sejam especialmente bons nem maus", "A magia não leva em conta nenhuma circunstância que possa mudar o resultado, como a conjuração de magias adicionais ou a perda ou chegada de um companheiro.", "Se você conjurar a magia duas ou mais vezes antes de concluir o próximo descanso longo, há 25% de chance cumulativa, a cada conjuração após a primeira, de receber uma leitura aleatória. O Mestre faz essa rolagem em segredo."] },
  { key: "barkskin", name: "Pele de Árvore", original: "Barkskin", level: 2, school: "transmutation", concentration: true, castingTime: "1 ação", range: "Toque", components: {"v": true, "s": true, "m": "um punhado de casca de carvalho"}, duration: "Concentração, até 1 hora", classes: ["druid", "ranger"], text: ["Você toca uma criatura voluntária. Até a magia terminar, a pele do alvo tem uma aparência áspera, semelhante a casca de árvore, e a CA do alvo não pode ser menor que 16, qualquer que seja a armadura que esteja vestindo."] },
  { key: "blindness_deafness", name: "Cegueira/Surdez", original: "Blindness/Deafness", level: 2, school: "necromancy", castingTime: "1 ação", range: "9 metros", components: {"v": true, "s": false}, duration: "1 minuto", classes: ["bard", "cleric", "sorcerer", "wizard"], text: ["Você pode cegar ou ensurdecer um inimigo. Escolha uma criatura que possa ver ao alcance para fazer uma salvaguarda de Constituição. Se falhar, o alvo fica cego ou surdo (à sua escolha) pela duração. No fim de cada um dos seus turnos, o alvo pode fazer uma salvaguarda de Constituição. Se for bem-sucedido, a magia termina."], higher: "Quando você conjura esta magia usando um espaço de magia de 3º nível ou superior, pode escolher uma criatura adicional como alvo para cada nível do espaço acima do 2º." },
  { key: "blur", name: "Borrão", original: "Blur", level: 2, school: "illusion", concentration: true, castingTime: "1 ação", range: "Pessoal", components: {"v": true, "s": false}, duration: "Concentração, até 1 minuto", classes: ["sorcerer", "wizard"], text: ["Seu corpo fica desfocado, oscilando e tremulando para todos que podem vê-lo. Pela duração, qualquer criatura tem desvantagem nas jogadas de ataque contra você. Um atacante é imune a esse efeito se não depender da visão, como com visão às cegas, ou se puder enxergar através de ilusões, como com visão verdadeira."] },
  { key: "branding_smite", name: "Golpe Marcante", original: "Branding Smite", level: 2, school: "evocation", concentration: true, castingTime: "1 ação bônus", range: "Pessoal", components: {"v": true, "s": false}, duration: "Concentração, até 1 minuto", classes: ["paladin"], text: ["Na próxima vez que você acertar uma criatura com um ataque com arma antes de a magia terminar, a arma reluz com um brilho astral ao golpear. O ataque causa 2d6 de dano radiante extra ao alvo, que se torna visível se estiver invisível, e o alvo emite penumbra num raio de 1,5 metro e não pode ficar invisível até a magia terminar."], higher: "Quando você conjura esta magia usando um espaço de magia de 3º nível ou superior, o dano extra aumenta em 1d6 para cada nível do espaço acima do 2º." },
  { key: "calm_emotions", name: "Acalmar Emoções", original: "Calm Emotions", level: 2, school: "enchantment", concentration: true, castingTime: "1 ação", range: "18 metros", components: {"v": true, "s": true}, duration: "Concentração, até 1 minuto", classes: ["bard", "cleric"], text: ["Você tenta suprimir emoções fortes num grupo de pessoas. Cada humanoide numa esfera de 6 metros de raio centrada num ponto à sua escolha ao alcance precisa fazer uma salvaguarda de Carisma; uma criatura pode escolher falhar nessa salvaguarda, se quiser. Se uma criatura falhar na salvaguarda, escolha um dos dois efeitos a seguir.", "Você pode suprimir qualquer efeito que deixe um alvo enfeitiçado ou amedrontado. Quando a magia termina, qualquer efeito suprimido volta, desde que sua duração não tenha acabado nesse meio-tempo.", "Alternativamente, você pode tornar um alvo indiferente a criaturas à sua escolha com as quais ele seja hostil. Essa indiferença termina se o alvo for atacado ou ferido por uma magia ou se presenciar algum amigo seu sendo ferido. Quando a magia termina, a criatura volta a ser hostil, a menos que o Mestre decida o contrário."] },
  { key: "continual_flame", name: "Chama Contínua", original: "Continual Flame", level: 2, school: "evocation", castingTime: "1 ação", range: "Toque", components: {"v": true, "s": true, "m": "pó de rubi no valor de 50 po, que a magia consome"}, duration: "Até ser dissipada", classes: ["cleric", "wizard"], text: ["Uma chama, equivalente em brilho a uma tocha, surge de um objeto que você toca. O efeito parece uma chama comum, mas não gera calor e não consome oxigênio. Uma chama contínua pode ser coberta ou escondida, mas não sufocada nem apagada."] },
  { key: "darkness", name: "Escuridão", original: "Darkness", level: 2, school: "evocation", concentration: true, castingTime: "1 ação", range: "18 metros", components: {"v": true, "s": false, "m": "pelo de morcego e uma gota de piche ou pedaço de carvão"}, duration: "Concentração, até 10 minutos", classes: ["sorcerer", "warlock", "wizard"], text: ["Escuridão mágica se espalha a partir de um ponto à sua escolha ao alcance, preenchendo uma esfera de 4,5 metros de raio pela duração. A escuridão contorna esquinas. Uma criatura com visão no escuro não consegue enxergar através dessa escuridão, e luz não mágica não consegue iluminá-la.", "Se o ponto escolhido estiver num objeto que você esteja segurando ou que não esteja sendo vestido ou carregado, a escuridão emana do objeto e se move com ele. Cobrir completamente a fonte da escuridão com um objeto opaco, como uma tigela ou um elmo, bloqueia a escuridão.", "Se qualquer parte da área desta magia se sobrepuser a uma área de luz criada por uma magia de 2º nível ou inferior, a magia que criou a luz é dissipada."] },
  { key: "darkvision", name: "Visão no Escuro", original: "Darkvision", level: 2, school: "transmutation", castingTime: "1 ação", range: "Toque", components: {"v": true, "s": true, "m": "uma pitada de cenoura seca ou uma ágata"}, duration: "8 horas", classes: ["druid", "ranger", "sorcerer", "wizard"], text: ["Você toca uma criatura voluntária para lhe conceder a capacidade de enxergar no escuro. Pela duração, essa criatura tem visão no escuro com alcance de 18 metros."] },
  { key: "detect_thoughts", name: "Detectar Pensamentos", original: "Detect Thoughts", level: 2, school: "divination", concentration: true, castingTime: "1 ação", range: "Pessoal", components: {"v": true, "s": true, "m": "uma moeda de cobre"}, duration: "Concentração, até 1 minuto", classes: ["bard", "sorcerer", "wizard"], text: ["Pela duração, você pode ler os pensamentos de certas criaturas. Ao conjurar a magia, e com sua ação em cada turno até ela terminar, você pode concentrar a mente em qualquer criatura que possa ver a até 9 metros de você. Se a criatura escolhida tiver Inteligência 3 ou menos ou não falar nenhum idioma, ela não é afetada.", "Inicialmente, você descobre os pensamentos superficiais da criatura, o que mais ocupa a mente dela naquele momento. Com uma ação, você pode desviar sua atenção para os pensamentos de outra criatura ou tentar sondar mais fundo a mente da mesma criatura. Se sondar mais fundo, o alvo precisa fazer uma salvaguarda de Sabedoria. Se falhar, você percebe o raciocínio dele (se houver), seu estado emocional e algo que ocupa grande espaço na sua mente (como algo que o preocupa, que ele ama ou odeia). Se for bem-sucedido, a magia termina. De qualquer forma, o alvo sabe que você está sondando a mente dele e, a menos que você desvie a atenção para os pensamentos de outra criatura, ela pode usar a ação no próprio turno para fazer um teste de Inteligência contestado pelo seu teste de Inteligência; se for bem-sucedida, a magia termina.", "Perguntas dirigidas verbalmente à criatura alvo moldam naturalmente o curso dos pensamentos dela, então esta magia é particularmente eficaz como parte de um interrogatório.", "Você também pode usar esta magia para detectar a presença de criaturas pensantes que não pode ver. Ao conjurar a magia ou com sua ação durante a duração, você pode procurar pensamentos a até 9 metros de você. A magia penetra barreiras, mas 60 cm de rocha, 5 cm de qualquer metal que não seja chumbo ou uma folha fina de chumbo bloqueiam você. Você não pode detectar uma criatura com Inteligência 3 ou menos ou que não fale nenhum idioma.", "Depois de detectar a presença de uma criatura dessa forma, você pode ler os pensamentos dela pelo resto da duração, como descrito acima, mesmo que não a veja, mas ela ainda precisa estar ao alcance."] },
  { key: "enhance_ability", name: "Aprimorar Habilidade", original: "Enhance Ability", level: 2, school: "transmutation", concentration: true, castingTime: "1 ação", range: "Toque", components: {"v": true, "s": true, "m": "pelo ou pena de um animal"}, duration: "Concentração, até 1 hora", classes: ["bard", "cleric", "druid", "sorcerer"], text: ["Você toca uma criatura e lhe concede um aprimoramento mágico. Escolha um dos efeitos a seguir; o alvo recebe esse efeito até a magia terminar.", "Resistência do Urso. O alvo tem vantagem em testes de Constituição. Ele também recebe 2d6 pontos de vida temporários, que são perdidos quando a magia termina.", "Força do Touro. O alvo tem vantagem em testes de Força, e sua capacidade de carga dobra.", "Graça do Gato. O alvo tem vantagem em testes de Destreza. Ele também não sofre dano de queda de até 6 metros, se não estiver incapacitado.", "Esplendor da Águia. O alvo tem vantagem em testes de Carisma.", "Astúcia da Raposa. O alvo tem vantagem em testes de Inteligência.", "Sabedoria da Coruja. O alvo tem vantagem em testes de Sabedoria."], higher: "Quando você conjura esta magia usando um espaço de magia de 3º nível ou superior, pode escolher uma criatura adicional como alvo para cada nível do espaço acima do 2º." },
  { key: "enlarge_reduce", name: "Aumentar/Reduzir", original: "Enlarge/Reduce", level: 2, school: "transmutation", concentration: true, castingTime: "1 ação", range: "9 metros", components: {"v": true, "s": true, "m": "uma pitada de ferro em pó"}, duration: "Concentração, até 1 minuto", classes: ["sorcerer", "wizard"], text: ["Você faz uma criatura ou um objeto que possa ver ao alcance crescer ou diminuir pela duração. Escolha uma criatura ou um objeto que não esteja sendo vestido nem carregado. Se o alvo for involuntário, ele pode fazer uma salvaguarda de Constituição. Se for bem-sucedido, a magia não tem efeito.", "Se o alvo for uma criatura, tudo que ela estiver vestindo e carregando muda de tamanho com ela. Qualquer item largado por uma criatura afetada volta imediatamente ao tamanho normal.", "Aumentar. O tamanho do alvo dobra em todas as dimensões, e seu peso é multiplicado por oito. Esse crescimento aumenta seu tamanho em uma categoria, de Médio para Grande, por exemplo. Se não houver espaço suficiente para o alvo dobrar de tamanho, a criatura ou objeto atinge o tamanho máximo possível no espaço disponível. Até a magia terminar, o alvo também tem vantagem em testes de Força e salvaguardas de Força. As armas do alvo também crescem para acompanhar seu novo tamanho. Enquanto essas armas estiverem aumentadas, os ataques do alvo com elas causam 1d4 de dano extra.", "Reduzir. O tamanho do alvo é reduzido pela metade em todas as dimensões, e seu peso cai para um oitavo do normal. Essa redução diminui seu tamanho em uma categoria, de Médio para Pequeno, por exemplo. Até a magia terminar, o alvo também tem desvantagem em testes de Força e salvaguardas de Força. As armas do alvo também encolhem para acompanhar seu novo tamanho. Enquanto essas armas estiverem reduzidas, os ataques do alvo com elas causam 1d4 a menos de dano (isso não pode reduzir o dano abaixo de 1)."] },
  { key: "enthrall", name: "Fascinar", original: "Enthrall", level: 2, school: "enchantment", castingTime: "1 ação", range: "18 metros", components: {"v": true, "s": true}, duration: "1 minuto", classes: ["bard", "warlock"], text: ["Você tece uma sequência de palavras que distrai, fazendo criaturas à sua escolha que você possa ver ao alcance e que possam ouvi-lo fazerem uma salvaguarda de Sabedoria. Qualquer criatura que não possa ser enfeitiçada é bem-sucedida nessa salvaguarda automaticamente, e se você ou seus companheiros estiverem lutando contra uma criatura, ela tem vantagem na salvaguarda. Se falhar, o alvo tem desvantagem em testes de Sabedoria (Percepção) feitos para perceber qualquer criatura que não seja você, até a magia terminar ou até o alvo não conseguir mais ouvi-lo. A magia termina se você ficar incapacitado ou não puder mais falar."] },
  { key: "find_steed", name: "Convocar Montaria", original: "Find Steed", level: 2, school: "conjuration", castingTime: "10 minutos", range: "9 metros", components: {"v": true, "s": true}, duration: "Instantânea", classes: ["paladin"], text: ["Você convoca um espírito que assume a forma de uma montaria excepcionalmente inteligente, forte e leal, criando um vínculo duradouro com ela. Surgindo num espaço desocupado ao alcance, a montaria assume uma forma à sua escolha: cavalo de guerra, pônei, camelo, alce ou mastim. (Seu Mestre pode permitir que outros animais sejam convocados como montarias.) A montaria tem as estatísticas da forma escolhida, embora seja um celestial, fada ou ínfero (à sua escolha) em vez do seu tipo normal. Além disso, se a montaria tiver Inteligência 5 ou menos, sua Inteligência passa a ser 6, e ela ganha a capacidade de entender um idioma à sua escolha que você fale.", "Sua montaria serve você como cavalgadura, dentro e fora de combate, e vocês têm um vínculo instintivo que permite lutar como uma unidade perfeita. Enquanto estiver montado, você pode fazer com que qualquer magia que conjure e tenha só você como alvo também tenha sua montaria como alvo.", "Quando a montaria chega a 0 pontos de vida, ela desaparece, sem deixar forma física. Você também pode dispensar a montaria a qualquer momento com uma ação, fazendo-a desaparecer. Em ambos os casos, conjurar esta magia de novo convoca a mesma montaria, restaurada ao máximo de pontos de vida.", "Enquanto a montaria estiver a até 1,5 km de você, vocês podem se comunicar telepaticamente.", "Você não pode ter mais de uma montaria ligada a você por esta magia ao mesmo tempo. Com uma ação, você pode libertar a montaria do vínculo a qualquer momento, fazendo-a desaparecer."] },
  { key: "find_traps", name: "Encontrar Armadilhas", original: "Find Traps", level: 2, school: "divination", castingTime: "1 ação", range: "36 metros", components: {"v": true, "s": true}, duration: "Instantânea", classes: ["cleric", "druid", "ranger"], text: ["Você percebe a presença de qualquer armadilha ao alcance que esteja na sua linha de visão. Uma armadilha, para os fins desta magia, inclui qualquer coisa que causaria um efeito súbito ou inesperado que você considere prejudicial ou indesejável, e que tenha sido especificamente concebida como tal por seu criador. Assim, a magia perceberia uma área afetada pela magia alarme, um glifo de proteção ou uma armadilha mecânica de fosso, mas não revelaria uma fraqueza natural no piso, um teto instável ou um sumidouro oculto.", "Esta magia apenas revela que há uma armadilha presente. Você não descobre a localização de cada armadilha, mas descobre a natureza geral do perigo representado por uma armadilha que perceber."] },
  { key: "flame_blade", name: "Lâmina de Fogo", original: "Flame Blade", level: 2, school: "evocation", concentration: true, castingTime: "1 ação bônus", range: "Pessoal", components: {"v": true, "s": true, "m": "uma folha de sumagre"}, duration: "Concentração, até 10 minutos", classes: ["druid"], text: ["Você evoca uma lâmina flamejante na sua mão livre. A lâmina tem tamanho e forma semelhantes a uma cimitarra e dura pela duração. Se você soltar a lâmina, ela desaparece, mas pode evocá-la de novo com uma ação bônus.", "Você pode usar sua ação para fazer um ataque de magia corpo a corpo com a lâmina flamejante. Se acertar, o alvo sofre 3d6 de dano de fogo.", "A lâmina flamejante emite luz plena num raio de 3 metros e penumbra por mais 3 metros."], higher: "Quando você conjura esta magia usando um espaço de magia de 4º nível ou superior, o dano aumenta em 1d6 para cada dois níveis do espaço acima do 2º." },
  { key: "flaming_sphere", name: "Esfera Flamejante", original: "Flaming Sphere", level: 2, school: "conjuration", concentration: true, castingTime: "1 ação", range: "18 metros", components: {"v": true, "s": true, "m": "um pouco de sebo, uma pitada de enxofre e um punhado de ferro em pó"}, duration: "Concentração, até 1 minuto", classes: ["druid", "wizard"], text: ["Uma esfera de fogo de 1,5 metro de diâmetro surge num espaço desocupado à sua escolha ao alcance e dura pela duração. Qualquer criatura que termine o turno a até 1,5 metro da esfera precisa fazer uma salvaguarda de Destreza. A criatura sofre 2d6 de dano de fogo se falhar, ou metade desse dano se for bem-sucedida.", "Com uma ação bônus, você pode mover a esfera até 9 metros. Se você jogar a esfera contra uma criatura, essa criatura precisa fazer a salvaguarda contra o dano da esfera, e a esfera para de se mover neste turno.", "Ao mover a esfera, você pode conduzi-la sobre barreiras de até 1,5 metro de altura e fazê-la saltar por cima de fossos de até 3 metros de largura. A esfera incendeia objetos inflamáveis que não estejam sendo vestidos ou carregados, e emite luz plena num raio de 6 metros e penumbra por mais 6 metros."], higher: "Quando você conjura esta magia usando um espaço de magia de 3º nível ou superior, o dano aumenta em 1d6 para cada nível do espaço acima do 2º." },
  { key: "gentle_repose", name: "Descanso Tranquilo", original: "Gentle Repose", level: 2, school: "necromancy", ritual: true, castingTime: "1 ação", range: "Toque", components: {"v": true, "s": true, "m": "uma pitada de sal e uma moeda de cobre colocada sobre cada olho do cadáver, que precisam permanecer ali pela duração"}, duration: "10 dias", classes: ["cleric", "wizard"], text: ["Você toca um cadáver ou outros restos mortais. Pela duração, o alvo fica protegido contra decomposição e não pode se tornar morto-vivo.", "A magia também estende efetivamente o limite de tempo para ressuscitar o alvo, já que os dias passados sob a influência desta magia não contam para o limite de tempo de magias como reviver os mortos."] },
  { key: "gust_of_wind", name: "Lufada de Vento", original: "Gust of Wind", level: 2, school: "evocation", concentration: true, castingTime: "1 ação", range: "Pessoal (linha de 18 metros)", components: {"v": true, "s": true, "m": "uma semente de leguminosa"}, duration: "Concentração, até 1 minuto", classes: ["druid", "sorcerer", "wizard"], text: ["Uma linha de vento forte, com 18 metros de comprimento e 3 metros de largura, sopra de você na direção que escolher pela duração da magia. Cada criatura que começar o turno na linha precisa ser bem-sucedida em uma salvaguarda de Força ou será empurrada 4,5 metros para longe de você, seguindo a direção da linha.", "Qualquer criatura na linha precisa gastar 60 cm de movimento para cada 30 cm que se mover ao se aproximar de você.", "A rajada dispersa gás ou vapor e apaga velas, tochas e chamas desprotegidas semelhantes na área. Ela faz chamas protegidas, como as de lanternas, dançarem descontroladamente e tem 50% de chance de apagá-las.", "Com uma ação bônus em cada um dos seus turnos antes de a magia terminar, você pode mudar a direção em que a linha sopra a partir de você."] },
  { key: "heat_metal", name: "Metal Quente", original: "Heat Metal", level: 2, school: "transmutation", concentration: true, castingTime: "1 ação", range: "18 metros", components: {"v": true, "s": true, "m": "um pedaço de ferro e uma chama"}, duration: "Concentração, até 1 minuto", classes: ["bard", "druid"], text: ["Escolha um objeto de metal manufaturado, como uma arma de metal ou uma armadura pesada ou média de metal, que você possa ver ao alcance. Você faz o objeto ficar em brasa. Qualquer criatura em contato físico com o objeto sofre 2d8 de dano de fogo quando você conjura a magia. Até a magia terminar, você pode usar uma ação bônus em cada um dos seus turnos seguintes para causar esse dano novamente.", "Se uma criatura estiver segurando ou vestindo o objeto e sofrer o dano dele, ela precisa ser bem-sucedida em uma salvaguarda de Constituição ou largará o objeto, se puder. Se não largar o objeto, ela tem desvantagem nas jogadas de ataque e testes de habilidade até o início do seu próximo turno."], higher: "Quando você conjura esta magia usando um espaço de magia de 3º nível ou superior, o dano aumenta em 1d8 para cada nível do espaço acima do 2º." },
  { key: "hold_person", name: "Imobilizar Pessoa", original: "Hold Person", level: 2, school: "enchantment", concentration: true, castingTime: "1 ação", range: "18 metros", components: {"v": true, "s": true, "m": "um pequeno pedaço reto de ferro"}, duration: "Concentração, até 1 minuto", classes: ["bard", "cleric", "druid", "sorcerer", "warlock", "wizard"], text: ["Escolha um humanoide que você possa ver ao alcance. O alvo precisa ser bem-sucedido em uma salvaguarda de Sabedoria ou ficará paralisado pela duração. No fim de cada um dos seus turnos, o alvo pode fazer outra salvaguarda de Sabedoria. Se for bem-sucedido, a magia termina para ele."], higher: "Quando você conjura esta magia usando um espaço de magia de 3º nível ou superior, pode escolher um humanoide adicional como alvo para cada nível do espaço acima do 2º. Os humanoides precisam estar a até 9 metros uns dos outros quando você os escolhe." },
  { key: "invisibility", name: "Invisibilidade", original: "Invisibility", level: 2, school: "illusion", concentration: true, castingTime: "1 ação", range: "Toque", components: {"v": true, "s": true, "m": "um cílio envolto em goma arábica"}, duration: "Concentração, até 1 hora", classes: ["bard", "sorcerer", "warlock", "wizard"], text: ["Uma criatura que você toca fica invisível até a magia terminar. Tudo que o alvo estiver vestindo ou carregando fica invisível enquanto estiver com ele. A magia termina para um alvo que ataque ou conjure uma magia."], higher: "Quando você conjura esta magia usando um espaço de magia de 3º nível ou superior, pode escolher uma criatura adicional como alvo para cada nível do espaço acima do 2º." },
  { key: "knock", name: "Arrombar", original: "Knock", level: 2, school: "transmutation", castingTime: "1 ação", range: "18 metros", components: {"v": true, "s": false}, duration: "Instantânea", classes: ["bard", "sorcerer", "wizard"], text: ["Escolha um objeto que possa ver ao alcance. O objeto pode ser uma porta, caixa, baú, par de algemas, cadeado ou outro objeto que tenha um meio mundano ou mágico de impedir o acesso.", "Um alvo mantido fechado por uma fechadura mundana, ou que esteja emperrado ou travado, fica destrancado, desemperrado ou destravado. Se o objeto tiver várias fechaduras, apenas uma delas é destrancada.", "Se você escolher um alvo mantido fechado por tranca arcana, essa magia é suprimida por 10 minutos, tempo durante o qual o alvo pode ser aberto e fechado normalmente.", "Ao conjurar a magia, uma batida alta, audível a até 90 metros de distância, emana do objeto alvo."] },
  { key: "lesser_restoration", name: "Restauração Menor", original: "Lesser Restoration", level: 2, school: "abjuration", castingTime: "1 ação", range: "Toque", components: {"v": true, "s": true}, duration: "Instantânea", classes: ["bard", "cleric", "druid", "paladin", "ranger"], text: ["Você toca uma criatura e pode encerrar uma doença ou uma condição que a aflija. A condição pode ser cegueira, surdez, paralisia ou envenenamento."] },
  { key: "levitate", name: "Levitação", original: "Levitate", level: 2, school: "transmutation", concentration: true, castingTime: "1 ação", range: "18 metros", components: {"v": true, "s": true, "m": "uma pequena argola de couro ou um pedaço de fio de ouro dobrado em forma de taça, com uma haste longa numa das pontas"}, duration: "Concentração, até 10 minutos", classes: ["sorcerer", "wizard"], text: ["Uma criatura ou objeto à sua escolha que você possa ver ao alcance se eleva verticalmente até 6 metros e permanece suspenso ali pela duração. A magia pode levitar um alvo que pese até 250 kg. Uma criatura involuntária que seja bem-sucedida em uma salvaguarda de Constituição não é afetada.", "O alvo só pode se mover empurrando ou puxando um objeto ou superfície fixa ao seu alcance (como uma parede ou teto), o que lhe permite se mover como se estivesse escalando. Você pode mudar a altitude do alvo em até 6 metros em qualquer direção no seu turno. Se você for o alvo, pode subir ou descer como parte do seu movimento. Caso contrário, pode usar sua ação para mover o alvo, que precisa permanecer dentro do alcance da magia.", "Quando a magia termina, o alvo flutua suavemente até o chão, se ainda estiver no ar."] },
  { key: "locate_animals_or_plants", name: "Localizar Animais ou Plantas", original: "Locate Animals or Plants", level: 2, school: "divination", ritual: true, castingTime: "1 ação", range: "Pessoal", components: {"v": true, "s": true, "m": "um pouco de pelo de um cão de caça"}, duration: "Instantânea", classes: ["bard", "druid", "ranger"], text: ["Descreva ou diga o nome de um tipo específico de animal ou planta. Concentrando-se na voz da natureza ao seu redor, você descobre a direção e a distância até a criatura ou planta mais próxima desse tipo a até 7,5 km, se houver alguma."] },
  { key: "locate_object", name: "Localizar Objeto", original: "Locate Object", level: 2, school: "divination", concentration: true, castingTime: "1 ação", range: "Pessoal", components: {"v": true, "s": true, "m": "um galho bifurcado"}, duration: "Concentração, até 10 minutos", classes: ["bard", "cleric", "druid", "paladin", "ranger", "wizard"], text: ["Descreva ou diga o nome de um objeto que lhe seja familiar. Você percebe a direção do local do objeto, desde que ele esteja a até 300 metros de você. Se o objeto estiver em movimento, você sabe a direção em que ele se move.", "A magia pode localizar um objeto específico conhecido por você, desde que você o tenha visto de perto, a até 9 metros, pelo menos uma vez. Alternativamente, a magia pode localizar o objeto mais próximo de um tipo particular, como um certo tipo de roupa, joia, mobília, ferramenta ou arma.", "Esta magia não consegue localizar um objeto se qualquer espessura de chumbo, mesmo uma folha fina, bloquear um caminho direto entre você e o objeto."] },
  { key: "magic_mouth", name: "Boca Mágica", original: "Magic Mouth", level: 2, school: "illusion", ritual: true, castingTime: "1 minuto", range: "9 metros", components: {"v": true, "s": true, "m": "um pequeno favo de mel e pó de jade no valor de pelo menos 10 po, que a magia consome"}, duration: "Até ser dissipada", classes: ["bard", "wizard"], text: ["Você implanta uma mensagem num objeto ao alcance, uma mensagem que é pronunciada quando uma condição de gatilho é atendida. Escolha um objeto que possa ver e que não esteja sendo vestido ou carregado por outra criatura. Então diga a mensagem, que precisa ter 25 palavras ou menos, embora possa ser entregue ao longo de até 10 minutos. Por fim, determine a circunstância que fará a magia entregar a mensagem.", "Quando essa circunstância ocorre, uma boca mágica surge no objeto e recita a mensagem com a sua voz e no mesmo volume em que você falou. Se o objeto escolhido tiver uma boca ou algo que pareça uma boca (por exemplo, a boca de uma estátua), a boca mágica surge ali, de modo que as palavras pareçam vir da boca do objeto. Ao conjurar a magia, você pode fazê-la terminar depois de entregar a mensagem, ou ela pode permanecer e repetir a mensagem sempre que o gatilho ocorrer.", "A circunstância de gatilho pode ser tão geral ou detalhada quanto você quiser, embora precise se basear em condições visuais ou audíveis que ocorram a até 9 metros do objeto. Por exemplo, você poderia instruir a boca a falar quando qualquer criatura se mover a até 9 metros do objeto ou quando um sino de prata tocar a até 9 metros dele."] },
  { key: "magic_weapon", name: "Arma Mágica", original: "Magic Weapon", level: 2, school: "transmutation", concentration: true, castingTime: "1 ação bônus", range: "Toque", components: {"v": true, "s": true}, duration: "Concentração, até 1 hora", classes: ["paladin", "wizard"], text: ["Você toca uma arma não mágica. Até a magia terminar, essa arma se torna uma arma mágica com +1 de bônus nas jogadas de ataque e de dano."], higher: "Quando você conjura esta magia usando um espaço de magia de 4º nível ou superior, o bônus aumenta para +2. Quando usa um espaço de 6º nível ou superior, o bônus aumenta para +3." },
  { key: "mirror_image", name: "Imagem Espelhada", original: "Mirror Image", level: 2, school: "illusion", castingTime: "1 ação", range: "Pessoal", components: {"v": true, "s": true}, duration: "1 minuto", classes: ["sorcerer", "warlock", "wizard"], text: ["Três duplicatas ilusórias de você surgem no seu espaço. Até a magia terminar, as duplicatas se movem com você e imitam suas ações, trocando de posição de modo que seja impossível saber qual imagem é a real. Você pode usar sua ação para dissipar as duplicatas ilusórias.", "Cada vez que uma criatura escolhe você como alvo de um ataque durante a duração da magia, role um d20 para determinar se o ataque, em vez disso, tem como alvo uma das suas duplicatas. Se você tiver três duplicatas, precisa tirar 6 ou mais para mudar o alvo do ataque para uma duplicata. Com duas duplicatas, precisa tirar 8 ou mais. Com uma duplicata, precisa tirar 11 ou mais.", "A CA de uma duplicata é igual a 10 + seu modificador de Destreza. Se um ataque acertar uma duplicata, ela é destruída. Uma duplicata só pode ser destruída por um ataque que a acerte. Ela ignora todo o outro dano e efeitos. A magia termina quando as três duplicatas são destruídas.", "Uma criatura não é afetada por esta magia se não puder ver, se depender de sentidos que não sejam a visão, como visão às cegas, ou se perceber ilusões como falsas, como com visão verdadeira."] },
  { key: "misty_step", name: "Passo Nebuloso", original: "Misty Step", level: 2, school: "conjuration", castingTime: "1 ação bônus", range: "Pessoal", components: {"v": true, "s": false}, duration: "Instantânea", classes: ["sorcerer", "warlock", "wizard"], text: ["Brevemente cercado por névoa prateada, você se teletransporta até 9 metros para um espaço desocupado que possa ver."] },
  { key: "moonbeam", name: "Raio Lunar", original: "Moonbeam", level: 2, school: "evocation", concentration: true, castingTime: "1 ação", range: "36 metros", components: {"v": true, "s": true, "m": "várias sementes de qualquer planta-lunar e um pedaço de feldspato opalescente"}, duration: "Concentração, até 1 minuto", classes: ["druid"], text: ["Um raio prateado de luz pálida brilha num cilindro de 1,5 metro de raio e 12 metros de altura centrado num ponto ao alcance. Até a magia terminar, penumbra preenche o cilindro.", "Quando uma criatura entra na área da magia pela primeira vez num turno ou começa o turno ali, ela é envolvida por chamas fantasmagóricas que causam uma dor abrasadora e precisa fazer uma salvaguarda de Constituição. Ela sofre 2d10 de dano radiante se falhar na salvaguarda, ou metade desse dano se for bem-sucedida.", "Um metamorfo faz a salvaguarda com desvantagem. Se falhar, ele também volta instantaneamente à sua forma original e não pode assumir outra forma até sair da luz da magia.", "Em cada um dos seus turnos após conjurar esta magia, você pode usar uma ação para mover o raio 18 metros em qualquer direção."], higher: "Quando você conjura esta magia usando um espaço de magia de 3º nível ou superior, o dano aumenta em 1d10 para cada nível do espaço acima do 2º." },
  { key: "pass_without_trace", name: "Passos sem Rastro", original: "Pass without Trace", level: 2, school: "abjuration", concentration: true, castingTime: "1 ação", range: "Pessoal", components: {"v": true, "s": true, "m": "cinzas de uma folha de visco queimada e um ramo de abeto"}, duration: "Concentração, até 1 hora", classes: ["druid", "ranger"], text: ["Um véu de sombras e silêncio irradia de você, escondendo você e seus companheiros da detecção. Pela duração, cada criatura que você escolher a até 9 metros de você (incluindo você) tem +10 de bônus em testes de Destreza (Furtividade) e não pode ser rastreada, exceto por meios mágicos. Uma criatura que receba esse bônus não deixa pegadas nem outros vestígios da sua passagem."] },
  { key: "prayer_of_healing", name: "Oração de Cura", original: "Prayer of Healing", level: 2, school: "evocation", castingTime: "10 minutos", range: "9 metros", components: {"v": true, "s": false}, duration: "Instantânea", classes: ["cleric"], text: ["Até seis criaturas à sua escolha que você possa ver ao alcance recuperam, cada uma, pontos de vida iguais a 2d8 + seu modificador de atributo de conjuração. Esta magia não tem efeito sobre mortos-vivos nem constructos."], higher: "Quando você conjura esta magia usando um espaço de magia de 3º nível ou superior, a cura aumenta em 1d8 para cada nível do espaço acima do 2º." },
  { key: "protection_from_poison", name: "Proteção contra Veneno", original: "Protection from Poison", level: 2, school: "abjuration", castingTime: "1 ação", range: "Toque", components: {"v": true, "s": true}, duration: "1 hora", classes: ["cleric", "druid", "paladin", "ranger"], text: ["Você toca uma criatura. Se ela estiver envenenada, você neutraliza o veneno. Se mais de um veneno afligir o alvo, você neutraliza um veneno que saiba estar presente, ou neutraliza um aleatoriamente.", "Pela duração, o alvo tem vantagem em salvaguardas contra ser envenenado e tem resistência a dano de veneno."] },
  { key: "ray_of_enfeeblement", name: "Raio do Enfraquecimento", original: "Ray of Enfeeblement", level: 2, school: "necromancy", concentration: true, castingTime: "1 ação", range: "18 metros", components: {"v": true, "s": true}, duration: "Concentração, até 1 minuto", classes: ["warlock", "wizard"], text: ["Um raio negro de energia debilitante surge do seu dedo em direção a uma criatura ao alcance. Faça um ataque de magia à distância contra o alvo. Se acertar, o alvo causa apenas metade do dano com ataques com arma que usem Força até a magia terminar.", "No fim de cada turno do alvo, ele pode fazer uma salvaguarda de Constituição contra a magia. Se for bem-sucedido, a magia termina."] },
  { key: "rope_trick", name: "Truque da Corda", original: "Rope Trick", level: 2, school: "transmutation", castingTime: "1 ação", range: "Toque", components: {"v": true, "s": true, "m": "extrato de milho em pó e uma espiral torcida de pergaminho"}, duration: "1 hora", classes: ["wizard"], text: ["Você toca um pedaço de corda de até 18 metros de comprimento. Uma ponta da corda então se ergue no ar até a corda inteira ficar suspensa perpendicular ao chão. Na ponta superior da corda, uma entrada invisível se abre para um espaço extradimensional que dura até a magia terminar.", "O espaço extradimensional pode ser alcançado subindo até o topo da corda. O espaço comporta até oito criaturas de tamanho Médio ou menor. A corda pode ser puxada para dentro do espaço, fazendo-a desaparecer da vista do lado de fora.", "Ataques e magias não podem atravessar a entrada para dentro ou para fora do espaço extradimensional, mas quem está dentro pode ver o exterior como se por uma janela de 90 cm por 1,5 metro centrada na corda.", "Tudo que estiver dentro do espaço extradimensional cai para fora quando a magia termina."] },
  { key: "scorching_ray", name: "Raio Ardente", original: "Scorching Ray", level: 2, school: "evocation", castingTime: "1 ação", range: "36 metros", components: {"v": true, "s": true}, duration: "Instantânea", classes: ["sorcerer", "wizard"], text: ["Você cria três raios de fogo e os arremessa contra alvos ao alcance. Você pode arremessá-los contra um alvo ou vários.", "Faça um ataque de magia à distância para cada raio. Se acertar, o alvo sofre 2d6 de dano de fogo."], higher: "Quando você conjura esta magia usando um espaço de magia de 3º nível ou superior, você cria um raio adicional para cada nível do espaço acima do 2º." },
  { key: "see_invisibility", name: "Ver Invisibilidade", original: "See Invisibility", level: 2, school: "divination", castingTime: "1 ação", range: "Pessoal", components: {"v": true, "s": true, "m": "uma pitada de talco e uma pequena aspersão de prata em pó"}, duration: "1 hora", classes: ["bard", "sorcerer", "wizard"], text: ["Pela duração, você enxerga criaturas e objetos invisíveis como se fossem visíveis, e pode enxergar o Plano Etéreo. Criaturas e objetos etéreos aparecem fantasmagóricos e translúcidos."] },
  { key: "shatter", name: "Despedaçar", original: "Shatter", level: 2, school: "evocation", castingTime: "1 ação", range: "18 metros", components: {"v": true, "s": true, "m": "um fragmento de mica"}, duration: "Instantânea", classes: ["bard", "sorcerer", "warlock", "wizard"], text: ["Um ruído súbito e estridente, dolorosamente intenso, irrompe de um ponto à sua escolha ao alcance. Cada criatura numa esfera de 3 metros de raio centrada nesse ponto precisa fazer uma salvaguarda de Constituição. Uma criatura sofre 3d8 de dano trovejante se falhar, ou metade desse dano se for bem-sucedida. Uma criatura feita de material inorgânico, como pedra, cristal ou metal, tem desvantagem nessa salvaguarda.", "Um objeto não mágico que não esteja sendo vestido ou carregado também sofre o dano se estiver na área da magia."], higher: "Quando você conjura esta magia usando um espaço de magia de 3º nível ou superior, o dano aumenta em 1d8 para cada nível do espaço acima do 2º." },
  { key: "silence", name: "Silêncio", original: "Silence", level: 2, school: "illusion", ritual: true, concentration: true, castingTime: "1 ação", range: "36 metros", components: {"v": true, "s": true}, duration: "Concentração, até 10 minutos", classes: ["bard", "cleric", "ranger"], text: ["Pela duração, nenhum som pode ser criado dentro de uma esfera de 6 metros de raio centrada num ponto à sua escolha ao alcance, nem atravessá-la. Qualquer criatura ou objeto inteiramente dentro da esfera é imune a dano trovejante, e as criaturas ficam surdas enquanto estiverem inteiramente dentro dela. Conjurar uma magia que tenha componente verbal é impossível ali."] },
  { key: "spider_climb", name: "Escalar Aranha", original: "Spider Climb", level: 2, school: "transmutation", concentration: true, castingTime: "1 ação", range: "Toque", components: {"v": true, "s": true, "m": "uma gota de betume e uma aranha"}, duration: "Concentração, até 1 hora", classes: ["sorcerer", "warlock", "wizard"], text: ["Até a magia terminar, uma criatura voluntária que você toca ganha a capacidade de se mover para cima, para baixo e ao longo de superfícies verticais e de cabeça para baixo pelos tetos, mantendo as mãos livres. O alvo também ganha deslocamento de escalada igual ao seu deslocamento de caminhada."] },
  { key: "spike_growth", name: "Crescer Espinhos", original: "Spike Growth", level: 2, school: "transmutation", concentration: true, castingTime: "1 ação", range: "45 metros", components: {"v": true, "s": true, "m": "sete espinhos afiados ou sete galhinhos pequenos, cada um apontado"}, duration: "Concentração, até 10 minutos", classes: ["druid", "ranger"], text: ["O chão num raio de 6 metros centrado num ponto ao alcance se contorce e brota espinhos e farpas duros. A área se torna terreno difícil pela duração. Quando uma criatura se move para dentro ou dentro da área, ela sofre 2d4 de dano perfurante para cada 1,5 metro que percorrer.", "A transformação do chão é camuflada para parecer natural. Qualquer criatura que não possa ver a área no momento em que a magia é conjurada precisa fazer um teste de Sabedoria (Percepção) contra a CD de salvaguarda da sua magia para reconhecer o terreno como perigoso antes de entrar nele."] },
  { key: "spiritual_weapon", name: "Arma Espiritual", original: "Spiritual Weapon", level: 2, school: "evocation", castingTime: "1 ação bônus", range: "18 metros", components: {"v": true, "s": true}, duration: "1 minuto", classes: ["cleric"], text: ["Você cria uma arma espectral e flutuante ao alcance que dura pela duração ou até você conjurar esta magia de novo. Ao conjurar a magia, você pode fazer um ataque de magia corpo a corpo contra uma criatura a até 1,5 metro da arma. Se acertar, o alvo sofre dano de energia igual a 1d8 + seu modificador de atributo de conjuração.", "Com uma ação bônus no seu turno, você pode mover a arma até 6 metros e repetir o ataque contra uma criatura a até 1,5 metro dela.", "A arma pode ter a forma que você escolher. Clérigos de divindades associadas a uma arma específica (como São Cuthbert, conhecido por sua maça, e Thor, por seu martelo) fazem o efeito desta magia lembrar essa arma."], higher: "Quando você conjura esta magia usando um espaço de magia de 3º nível ou superior, o dano aumenta em 1d8 para cada dois níveis do espaço acima do 2º." },
  { key: "suggestion", name: "Sugestão", original: "Suggestion", level: 2, school: "enchantment", concentration: true, castingTime: "1 ação", range: "9 metros", components: {"v": true, "s": false, "m": "uma língua de serpente e um pouco de favo de mel ou uma gota de óleo doce"}, duration: "Concentração, até 8 horas", classes: ["bard", "sorcerer", "warlock", "wizard"], text: ["Você sugere um curso de ação (limitado a uma ou duas frases) e influencia magicamente uma criatura que possa ver ao alcance e que possa ouvir e entender você. Criaturas que não podem ser enfeitiçadas são imunes a esse efeito. A sugestão precisa ser formulada de modo que o curso de ação pareça razoável. Pedir à criatura que se apunhale, se jogue sobre uma lança, se imole ou faça qualquer outro ato obviamente prejudicial encerra a magia.", "O alvo precisa fazer uma salvaguarda de Sabedoria. Se falhar, ele segue o curso de ação que você descreveu da melhor forma possível. O curso de ação sugerido pode continuar por toda a duração. Se a atividade sugerida puder ser concluída em menos tempo, a magia termina quando o alvo terminar o que foi pedido.", "Você também pode especificar condições que disparem uma atividade especial durante a duração. Por exemplo, você pode sugerir que uma cavaleira entregue seu cavalo de guerra ao primeiro mendigo que encontrar. Se a condição não for atendida antes de a magia expirar, a atividade não é realizada.", "Se você ou algum dos seus companheiros causar dano ao alvo, a magia termina."] },
  { key: "warding_bond", name: "Vínculo de Proteção", original: "Warding Bond", level: 2, school: "abjuration", castingTime: "1 ação", range: "Toque", components: {"v": true, "s": true, "m": "um par de anéis de platina no valor de pelo menos 50 po cada, que você e o alvo precisam usar pela duração"}, duration: "1 hora", classes: ["cleric"], text: ["Esta magia protege uma criatura voluntária que você toca e cria uma conexão mística entre você e o alvo até a magia terminar. Enquanto o alvo estiver a até 18 metros de você, ele recebe +1 de bônus na CA e nas salvaguardas e tem resistência a todo dano. Além disso, cada vez que ele sofre dano, você sofre a mesma quantidade de dano.", "A magia termina se você chegar a 0 pontos de vida ou se você e o alvo ficarem separados por mais de 18 metros. Ela também termina se a magia for conjurada de novo sobre qualquer uma das criaturas conectadas. Você também pode dissipar a magia com uma ação."] },
  { key: "web", name: "Teia", original: "Web", level: 2, school: "conjuration", concentration: true, castingTime: "1 ação", range: "18 metros", components: {"v": true, "s": true, "m": "um pouco de teia de aranha"}, duration: "Concentração, até 1 hora", classes: ["sorcerer", "wizard"], text: ["Você conjura uma massa de teia grossa e pegajosa num ponto à sua escolha ao alcance. As teias preenchem um cubo de 6 metros a partir desse ponto pela duração. As teias são terreno difícil e obscurecem levemente sua área.", "Se as teias não estiverem ancoradas entre duas massas sólidas (como paredes ou árvores) ou dispostas em camadas sobre um piso, parede ou teto, a teia conjurada desmorona sobre si mesma, e a magia termina no início do seu próximo turno. Teias dispostas sobre uma superfície plana têm 1,5 metro de profundidade.", "Cada criatura que começar o turno nas teias ou entrar nelas durante o turno precisa fazer uma salvaguarda de Destreza. Se falhar, a criatura fica impedida enquanto permanecer nas teias ou até se libertar.", "Uma criatura impedida pelas teias pode usar a ação para fazer um teste de Força contra a CD de salvaguarda da sua magia. Se for bem-sucedida, ela deixa de estar impedida.", "As teias são inflamáveis. Qualquer cubo de 1,5 metro de teia exposto ao fogo queima em 1 rodada, causando 2d4 de dano de fogo a qualquer criatura que comece o turno no fogo."] },
  { key: "zone_of_truth", name: "Zona da Verdade", original: "Zone of Truth", level: 2, school: "enchantment", castingTime: "1 ação", range: "18 metros", components: {"v": true, "s": true}, duration: "10 minutos", classes: ["bard", "cleric", "paladin"], text: ["Você cria uma zona mágica que protege contra a mentira numa esfera de 4,5 metros de raio centrada num ponto à sua escolha ao alcance. Até a magia terminar, uma criatura que entre na área da magia pela primeira vez num turno ou comece o turno ali precisa fazer uma salvaguarda de Carisma. Se falhar, a criatura não consegue dizer uma mentira deliberada enquanto estiver no raio. Você sabe se cada criatura é bem-sucedida ou falha na salvaguarda.", "Uma criatura afetada tem consciência da magia e pode, portanto, evitar responder a perguntas que normalmente responderia com uma mentira. Essa criatura pode ser evasiva nas respostas, contanto que permaneça dentro dos limites da verdade."] },
]
